) AS (
  VALUES 
    (844::BIGINT, 'Exelente profe, se preocupa por los estudiantes y busca hacer sus clases lo mas entretenidas posibles>'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'c594410df4e2cd2fa2163d8275b6fe8383e894bb3d74ff70a00246aad6ec20c5'::TEXT, ARRAY[498]::BIGINT[]),
    (844::BIGINT, 'El profesor es muy amable y busca al estudiante para ayudarlo, las tareas que deja son fáciles de hacer si uno tiene imaginación para actuar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'c9af9a3089cf1ccb854f5114c99139460b9c55d92699d5197ec186ae2c757c70'::TEXT, ARRAY[653]::BIGINT[]),
    (844::BIGINT, 'Es entretenido, se aprende de obras famosas como Hamlet y Macbet que yo conocia poco. Hay tareas pero son rapidas y entretenidas, solo la primera sobre Romeo y Julieta lleva un poco mas de tiempo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'a40fe15187705b2c4790b361bc29a21d904abfde7545f9452c0f6594a75174a0'::TEXT, ARRAY[653]::BIGINT[]),
    (844::BIGINT, 'El profesor es demasiado genial, si le gusta la actuación, o hacer voces y quiere salir un poco de la rutina, este curso es el mejor. También hay opciones escritas si eso no es lo suyo, pero permite explotar la creatividad. 10000/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-14T00:00:00+00:00'::TIMESTAMPTZ, '5931dd57d72acb3e9760d8a0fed3a7ee291c95036757e382c5e4b77519217fe2'::TEXT, ARRAY[653]::BIGINT[]),
    (844::BIGINT, 'El profe es una teja, muy claro, divertido y siempre va al grano. La materia es simple, entretenida y las tareas requieren creatividad. Dele sin miedo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2023-09-28T00:00:00+00:00'::TIMESTAMPTZ, 'dbd5c18a35b4f735c52abfcedc4636e78d06dd82ec84c4ae123e525bd287a508'::TEXT, ARRAY[653]::BIGINT[]),
    (844::BIGINT, 'Es muy buena gente, a veces es un poco exigente con que se le envíen los trabajos a tiempo. Las clases son entretenidas y se aprende bastante'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'ab2574d124ec34a996d1d81210089a9e9253227084ac1478f06992a3c5f16b05'::TEXT, ARRAY[653]::BIGINT[]),
    (844::BIGINT, 'Me encanto la clase, muy bonita y creativa el profesor es muy comico e inpirador'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2023-06-13T00:00:00+00:00'::TIMESTAMPTZ, '28fcfea9d268a03c0789cc678314d8ab840d5a3693e663b861880ac7aaa3ab91'::TEXT, ARRAY[648]::BIGINT[]),
    (844::BIGINT, 'Tiene un formato de clase interesante , y despierta esas ganas de conocer más acerca de diferentes personajes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-13T00:00:00+00:00'::TIMESTAMPTZ, '776f2fa1f48a02e7f92ab594dcd0a18bb230e4f9a366b40de431f2e75cca263d'::TEXT, ARRAY[653]::BIGINT[]),
    (844::BIGINT, 'El CFH se pasa muy fácil con él, nadamás hay que presentarse a la clase y en lugar de quedarse las 3 horas ahí, da 2 horas de clse y 1 hora para que hagamos una tarea que cuenta como participación. La clase es entretenida entonces se pasa bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-05-22T00:00:00+00:00'::TIMESTAMPTZ, 'f6d045d31f3b108a3b76a14be4fa6bd9e49224a68faf33f2900f9be75d785793'::TEXT, ARRAY[653]::BIGINT[]),
    (844::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2023-05-09T00:00:00+00:00'::TIMESTAMPTZ, 'cb0c646ae2ca5627d372df348324d155648c39652158da077e8eeabb7c38b6d1'::TEXT, ARRAY[648]::BIGINT[]),
    (844::BIGINT, 'Excelente profesor, presenta actividades muy dinámicas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2023-03-21T00:00:00+00:00'::TIMESTAMPTZ, '9afe07561aadb0b4559d867954da9c1c175676695019a378f5bf0cf88861ae57'::TEXT, ARRAY[677]::BIGINT[]),
    (844::BIGINT, 'Las clases son muy entretenidas, se nota que le apasiona el tema. Las asignaciones que deja son sencillas y 100% las revisa.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-10-13T00:00:00+00:00'::TIMESTAMPTZ, '57d407428bd94a1cf1dfd6e889a0d63e7404b0d67de0d087481f6942dda369ed'::TEXT, ARRAY[677]::BIGINT[]),
    (844::BIGINT, 'Lo recomiendo mucho, se ve que sabe muchísimo del mundo artístico, explica muy bien y sus clases son entretenidas Las asignaciones que deja son bastante sencillas y creativas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '526d2214a8d58cfd88db0c2f2e4f08abb70203408046094efab5626c8eb3cd4c'::TEXT, ARRAY[653]::BIGINT[]),
    (844::BIGINT, 'Excelente profesor, el curso es bastante llevadero e interesante, hace que el estudiante se interese por los aspectos literarios y artísticos, después de cada clase deja una actividad que cuenta como asistencia, son súper sencillas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'aceccda3b5de7d3a8077b5ee8685704d7e2f104d453023237d7b9d7e5d852658'::TEXT, ARRAY[653]::BIGINT[]),
    (844::BIGINT, 'Genuinamente tomaría el curso una segunda vez, tanto por el curso en sí, como por el profesor que lo imparte. Super recomendado si van a llevar algún CFH o una cultural'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-24T00:00:00+00:00'::TIMESTAMPTZ, '76c9dc71f6d3372398b93fbd79ca353d4c2dc6192b8691cf180f3e7d14bbc350'::TEXT, ARRAY[653]::BIGINT[]),
    (844::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '42ea2cdd0e5cb4947c824d245b4d9da144f3ccc4a097dce3619fa68d0cd5d9e0'::TEXT, ARRAY[653]::BIGINT[]),
    (844::BIGINT, 'Excelente profesor, hace el curso bastante llevadero y las cuatros actividades que deja son de fomentar la creatividad y las clases no aburridas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'bca93103383f9f1140c3cfbe75c40396e91336998888861170fbf99bda985fb3'::TEXT, ARRAY[653]::BIGINT[]),
    (844::BIGINT, 'Divertido y amistoso, se nota que le gusta dar su clase. Su clase es muy interesante y entretenida, las asignaciones asincronicas son divertidas de realizar y fomentan la creatividad. Si tiene la oportunidad de llevar este centro con él ni lo dude, lo va a disfrutar al máximo!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2022-06-16T00:00:00+00:00'::TIMESTAMPTZ, '45bf7b2edf23a03635991eef1f6dfa4ed9f7564fae34a9139c4d34c2f6774462'::TEXT, ARRAY[653]::BIGINT[]),
    (844::BIGINT, 'Excelente profesor. 100% recomendado el centro. Fueron 4 clases, un trabajo asincrónico por clase, siempre nos dio suficiente tiempo para realizarlo y las tareas pueden ser tan largas o tan cortas como uno quiera. La asignación es fácil, queda a criterio propio si se hace regular, bien o excelente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-03-23T00:00:00+00:00'::TIMESTAMPTZ, '162952d3a3981a781c1c52bf75d28cc47bf7c3ce97ba450377a37bb93ba78cfa'::TEXT, ARRAY[653]::BIGINT[]),
    (844::BIGINT, 'Excelente profesor. Las clases son sumamente entretenidas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-03-23T00:00:00+00:00'::TIMESTAMPTZ, 'd25dd5aa5d33289adbc4a0010961af8e78e94a92d826a7d6cf9d7e72a0b605cd'::TEXT, ARRAY[653]::BIGINT[]),
    (844::BIGINT, 'Es un excelente profesor, las clases son super divertidas, las tareas muy fáciles y su objetivo ayuda demasiado para el desarrollo del curso y para el personal también... Si va a llevar artes dramáticas con él deje la vergüenza fuera del aula.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2022-01-24T00:00:00+00:00'::TIMESTAMPTZ, '5a2dc509943962dfd793ccaaf24888aef092060ad1fc6994745935cec56a6463'::TEXT, ARRAY[498]::BIGINT[]),
    (844::BIGINT, 'Es un profesor excelente, en general como profe es un 10. Lo único que encuentro llamativo es que escribe y de vez en cuando habla en lenguaje "inclusive" y eso es una clara falta a la morfología léxico-gráfica de nuestro idioma, lo cual me parece inadecuado en el ámbito académico.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'a01bab0434fce23ebd3f4d130e3a5f891bd59af52f94278f8b4d57f5e05afc62'::TEXT, ARRAY[498]::BIGINT[]),
    (844::BIGINT, 'Un muy buen profe, hace las clases muy entretenidas y se vacila bastante en el curso.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Clases excelentes']::TEXT[], '2022-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'f233f1af626859d05d84194ae08b5f8bbd1b7cf6f041a3dd3d1b92f4ba8bca03'::TEXT, ARRAY[498]::BIGINT[]),
    (844::BIGINT, 'Excelente profesor, las clases son muy entretenidas, se aprende, se disfruta y no es para nada pesado, una de las clases que más disfrute, el profe lo hace muy ameno y mejore mis habilidades blandas al mil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Inspirador']::TEXT[], '2022-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'd0a035405dc9316eff60c345af17fc7d99202ce99fce9c4b4657a8cffec52030'::TEXT, ARRAY[498]::BIGINT[]),
    (844::BIGINT, 'Es un profe demasiado buena nota, y es demasiado apasionado por el tema. Es muy comprensivo con las situaciones de cada estudiante y hace que uno pase un muy buen rato.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-21T00:00:00+00:00'::TIMESTAMPTZ, '968d025d73d1389528ae838410ae26bd019bd5b73b15d4698b03e69cd2d1baa1'::TEXT, ARRAY[498]::BIGINT[]),
    (844::BIGINT, 'Excelente curso, probablemente de las deportivas-culturales que más disfruté. El curso es para ser presencial, en clase se debe participar bastante, pero el profe sabe muy bien como hacer que los estudiantes se sientan cómodos participando por lo que no suele ser problema. Super recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-20T00:00:00+00:00'::TIMESTAMPTZ, '7bceee256498ee8c617688494d5324a88890b547a9a54a9e244e5cf57e8dcce2'::TEXT, ARRAY[498]::BIGINT[]),
    (844::BIGINT, 'Las clases son muy entretenidas y los trabajos que deja son faciles y divertidos, se aprende bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-10-15T00:00:00+00:00'::TIMESTAMPTZ, '06f7b08831a75c4c3ca9aafcca015606134866ae0aafb402798fadc9df7de287'::TEXT, ARRAY[653]::BIGINT[]),
    (844::BIGINT, 'El profesor hace que la clase sea muy amena. Aún para los que no estén interesados en el tema, el profe lo hace de tal manera que uno se interese y quiera participar. El mejor centro al que asistí y las tareas son sencillas y entretenidas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-09-30T00:00:00+00:00'::TIMESTAMPTZ, '2dfc4bcec04f710146ff86906aa8cacf8bf49b43026053abfaad98a26a836ef3'::TEXT, ARRAY[653]::BIGINT[]),
    (844::BIGINT, 'Profesor super dedicado a la materia, sabe un montón acerca de Shakespeare y acerca de las obras de teatro. Se nota mucho su pasión por el arte y las asignaciones son muy divertidas y fáciles de hacer. El mejor Cfh para llevar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Muchos exámenes', 'Brinda apoyo']::TEXT[], '2021-09-28T00:00:00+00:00'::TIMESTAMPTZ, '5d4822466c56c397a589ff05e7d4fffafbb254a629adc95d47b40647a300ad46'::TEXT, ARRAY[653]::BIGINT[]),
    (844::BIGINT, 'Aunque su centro de formación "La tragedia Shakespeareana" suena un poco aburrido, no lo es. El profe es demasiado amable y logra hacer que la clase sea muy divertida, es el mejor centro que he llevado. Si logran tener la oportunidad de meter este centro, no lo duden.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes']::TEXT[], '2020-09-02T00:00:00+00:00'::TIMESTAMPTZ, '2f08cce71e4c534d0eb8a6cb8a64ac673babd049500fc78689d52de10511afb4'::TEXT, ARRAY[648]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
